package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_HexInteger() {
        // Hex logic: startsWith 0x, hexDigits <= 8 -> createInteger
        assertEquals(Integer.valueOf(255), NumberUtils.createNumber("0xFF"));
        assertEquals(Integer.valueOf(-255), NumberUtils.createNumber("-0xFF"));
        assertEquals(Integer.valueOf(255), NumberUtils.createNumber("0XFF"));
        assertEquals(Integer.valueOf(-255), NumberUtils.createNumber("-0XFF"));
    }

    @Test
    public void testCreateNumber_HexLong() {
        // Hex logic: hexDigits > 8 -> createLong
        // "0x123456789" -> length 11. hexDigits = 11 - 2 = 9. 9 > 8.
        Number n = NumberUtils.createNumber("0x123456789");
        assertTrue(n instanceof Long);
        assertEquals(Long.parseLong("123456789", 16), n.longValue());
    }

    @Test
    public void testCreateNumber_Integer() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
    }

    @Test
    public void testCreateNumber_Long() {
        assertEquals(Long.valueOf(12345678901L), NumberUtils.createNumber("12345678901"));
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigStr = "123456789012345678901234567890";
        Number n = NumberUtils.createNumber(bigStr);
        assertTrue(n instanceof BigInteger);
        assertEquals(new BigInteger(bigStr), n);
    }

    @Test
    public void testCreateNumber_Float() {
        Number n = NumberUtils.createNumber("1.23f");
        assertTrue(n instanceof Float);
        assertEquals(1.23f, ((Float) n).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_Double() {
        Number n = NumberUtils.createNumber("1.23d");
        assertTrue(n instanceof Double);
        assertEquals(1.23, ((Double) n).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        // Test via fallback or decimal point
        Number n = NumberUtils.createNumber("1.234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_ScientificNotation_Float() {
        Number n = NumberUtils.createNumber("1.2e3f");
        assertTrue(n instanceof Float);
        assertEquals(1200.0f, ((Float) n).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_ScientificNotation_Double() {
        Number n = NumberUtils.createNumber("1.2e3d");
        assertTrue(n instanceof Double);
        assertEquals(1200.0, ((Double) n).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_ScientificNotation_NoSuffix() {
        Number n = NumberUtils.createNumber("1.2e3");
        assertTrue(n instanceof Double || n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        // The 'l'/'L' case is hardcoded to throw NFE in the provided snippet (if (false) block)
        try {
            NumberUtils.createNumber("123l");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidDecimalExp() {
        // Case: expPos < decPos (e.g., "1e2.3")
        NumberUtils.createNumber("1e2.3");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExpPos() {
        // Case: expPos > length
        NumberUtils.createNumber("1e"); 
    }

    @Test
    public void testCreateNumber_AllZerosCheck() {
        // Test the logic for allZeros (mantissa 0, exponent 0)
        // "0.0e0" -> mant=0, dec=0, exp=0. allZeros=true.
        // This affects the precision check logic
        Number n = NumberUtils.createNumber("0.0e0");
        assertNotNull(n);
    }

    @Test
    public void testCreateNumber_InvalidCharSuffix() {
        try {
            NumberUtils.createNumber("123x");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_FloatPrecisionFallback() {
        // Test case where float is too small/imprecise and falls through to Double
        // A very small number that might be represented as 0.0 in float but not in double
        Number n = NumberUtils.createNumber("0.0000000000000000000000000000000000000001");
        assertNotNull(n);
    }

    @Test
    public void testCreateNumber_DoublePrecisionFallback() {
        // Test case where double is too large and falls through to BigDecimal
        Number n = NumberUtils.createNumber("1e1000");
        assertTrue(n instanceof BigDecimal);
    }
}
